settings.customCss:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@500;600;700;800&family=Inter:wght@400;500;600&display=swap');
.mfp.mfp-teal-brochure{--tb-teal:#2A9D8F;--tb-teal-d:#1e7a6f;--tb-teal-l:#e8f5f3;--tb-teal-m:#b2ddd9;--tb-teal-r:#4bbfae;--tb-ink:#1e2a2a;--tb-mut:#4a5e5c;--tb-soft:#94a3a0;--tb-slate:#64748b;--tb-card:#f9fefe;--tb-dark-line:#2d3f3f;font-family:Inter,system-ui,-apple-system,'Segoe UI',sans-serif;color:var(--tb-ink)}
.mfp-teal-brochure,.mfp-teal-brochure *{box-sizing:border-box}
.mfp-teal-brochure .ey-shell{display:grid;grid-template-columns:1fr;min-height:auto;max-width:1152px;margin:0 auto;background:var(--tb-teal-l)}
/* ---------- HERO (teal brochure panel + charcoal foot) ---------- */
.mfp-teal-brochure .ey-hero{display:none;position:relative;overflow:hidden;isolation:isolate;background:var(--tb-teal)}
.mfp-teal-brochure .ey-hero-media{position:absolute;inset:0}
.mfp-teal-brochure .ey-hero-media img{display:block;width:100%;height:100%;object-fit:cover;opacity:.55;mix-blend-mode:luminosity}
.mfp-teal-brochure .ey-hero-veil{position:absolute;inset:0;z-index:1;background:linear-gradient(180deg,rgba(42,157,143,0) 0%,rgba(30,122,111,.35) 100%)}
.mfp-teal-brochure .ey-hero-inner{position:relative;z-index:2;flex:1 1 auto;min-height:320px;padding:28px}
.mfp-teal-brochure .ey-hero-cut{position:absolute;top:0;right:-1px;bottom:-1px;width:48px;z-index:1;background:#fff;clip-path:polygon(100% 0,100% 100%,0 100%);pointer-events:none}
.mfp-teal-brochure .ey-brand{position:relative;z-index:2;display:flex;align-items:center;gap:10px}
.mfp-teal-brochure .ey-brand-icon{display:flex;align-items:center;justify-content:center;width:36px;height:36px;flex:0 0 36px;border-radius:10px;background:rgba(255,255,255,.2);-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px);color:#fff}
.mfp-teal-brochure .ey-brand-icon svg{width:20px;height:20px}
.mfp-teal-brochure .ey-brand>span{font-size:14px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;line-height:1.2;color:rgba(255,255,255,.9)}
.mfp-teal-brochure .ey-hero-copy{position:relative;z-index:2;margin-top:24px}
.mfp-teal-brochure .ey-rating{display:inline-flex;align-items:center;gap:6px;margin-bottom:12px;border-radius:999px;background:rgba(255,255,255,.2);-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px);padding:4px 12px;font-size:12px;font-weight:500;line-height:1.3;color:#fff}
.mfp-teal-brochure .ey-rating svg{width:14px;height:14px;flex:0 0 14px;color:#fcd34d;fill:#fcd34d}
.mfp-teal-brochure .ey-hero h1{margin:0;font-size:clamp(1.5rem,2.4vw,1.875rem);line-height:1.25;font-weight:800;letter-spacing:-.01em}
.mfp.mfp-teal-brochure .ey-hero h1{color:#fff!important}
.mfp-teal-brochure .ey-hero-copy .ey-sub{margin:8px 0 0;font-size:14px;line-height:1.65;color:rgba(255,255,255,.8)}
.mfp-teal-brochure .ey-stats{display:flex;align-items:flex-start;gap:20px;margin-top:24px}
.mfp-teal-brochure .ey-stats strong{display:block;font-size:20px;line-height:1.15;font-weight:700;color:#fff}
.mfp-teal-brochure .ey-stats span{display:block;margin-top:2px;font-size:11px;line-height:1.2;color:rgba(255,255,255,.7)}
.mfp-teal-brochure .ey-hero-foot{position:relative;z-index:3;background:var(--tb-ink);padding:32px 28px}
.mfp-teal-brochure .ey-cap{margin:0 0 4px;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.1em;line-height:1.4;color:var(--tb-teal)}
.mfp-teal-brochure .ey-cap-team{margin-top:24px}
.mfp-teal-brochure .ey-mission{margin:0;font-size:13px;line-height:1.75;color:#cbd5e1}
.mfp-teal-brochure .ey-team{margin:12px 0 0;padding:0;list-style:none;display:grid;gap:16px}
.mfp-teal-brochure .ey-team li{display:flex;align-items:center;gap:12px}
.mfp-teal-brochure .ey-avatar{display:flex;align-items:center;justify-content:center;width:44px;height:44px;flex:0 0 44px;border-radius:999px;background:linear-gradient(135deg,var(--tb-teal) 0%,var(--tb-teal-d) 100%);box-shadow:0 0 0 2px var(--tb-teal-r);font-size:13px;font-weight:700;letter-spacing:.04em;color:#fff}
.mfp-teal-brochure .ey-team strong{display:block;font-size:13px;font-weight:600;line-height:1.3;color:#fff}
.mfp-teal-brochure .ey-role{display:block;margin-top:2px;font-size:11px;line-height:1.3;color:var(--tb-teal-m)}
.mfp-teal-brochure .ey-contact{display:grid;gap:8px;margin-top:24px;padding-top:20px;border-top:1px solid var(--tb-dark-line)}
.mfp-teal-brochure .ey-contact div{display:flex;align-items:center;gap:8px}
.mfp-teal-brochure .ey-contact svg{width:16px;height:16px;flex:0 0 16px;color:var(--tb-teal)}
.mfp-teal-brochure .ey-contact span{font-size:12px;line-height:1.3;color:#94a3b8}
/* ---------- PANEL / STEPPER ---------- */
.mfp-teal-brochure .ey-panel{display:flex;flex-direction:column;background:#fff;padding:32px 24px}
.mfp-teal-brochure .ey-progress{height:4px;width:100%;overflow:hidden;border-radius:999px;background:var(--tb-teal-l);margin-bottom:24px}
.mfp-teal-brochure .ey-progress i{display:block;height:100%;width:25%;border-radius:999px;background:var(--tb-teal);transition:width .45s ease}
.mfp-teal-brochure .ey-stepper{display:flex;align-items:flex-start;gap:6px;margin-bottom:32px}
.mfp-teal-brochure .ey-step{display:flex;flex-direction:column;align-items:center;gap:6px;flex:0 0 auto;text-align:center}
.mfp-teal-brochure .ey-dot{display:flex;align-items:center;justify-content:center;width:36px;height:36px;flex:0 0 36px;border-radius:999px;background:var(--tb-teal-l);color:var(--tb-teal);font-size:12px;font-weight:700;line-height:1;transition:all .18s ease}
.mfp-teal-brochure .ey-step.is-done .ey-dot{background:var(--tb-teal);color:#fff}
.mfp-teal-brochure .ey-step.is-active .ey-dot{background:var(--tb-teal);color:#fff;box-shadow:0 0 0 4px rgba(42,157,143,.15)}
.mfp-teal-brochure .ey-step-text{display:none}
.mfp-teal-brochure .ey-step-text strong{display:block;font-size:12px;font-weight:600;line-height:1;color:var(--tb-soft)}
.mfp-teal-brochure .ey-step.is-done .ey-step-text strong{color:var(--tb-teal-d)}
.mfp-teal-brochure .ey-step.is-active .ey-step-text strong{color:var(--tb-teal)}
.mfp-teal-brochure .ey-step-text span{display:block;margin-top:3px;font-size:10px;line-height:1.2;color:var(--tb-soft)}
.mfp-teal-brochure .ey-line{flex:1 1 auto;height:1px;margin:18px 6px 0;background:var(--tb-teal-m);transition:background .18s ease}
.mfp-teal-brochure .ey-line.is-done{background:var(--tb-teal)}
/* ---------- CARD / PAGES ---------- */
.mfp-teal-brochure .ey-card{flex:1;border:1.5px solid var(--tb-teal-m);border-radius:24px;background:var(--tb-card);padding:24px;box-shadow:0 1px 2px rgba(30,42,42,.05)}
.mfp-teal-brochure .ey-page{display:none}
.mfp-teal-brochure .ey-page.is-active{display:block}
.mfp-teal-brochure .ey-page .ey-eyebrow{margin:0 0 4px;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.1em;line-height:1.3;color:var(--tb-teal)}
.mfp-teal-brochure .ey-page h2{margin:0;font-size:1.5rem;line-height:1.3;font-weight:700;color:var(--tb-ink)}
.mfp-teal-brochure .ey-lede{margin:4px 0 0;font-size:14px;line-height:1.65;color:var(--tb-mut)}
.mfp-teal-brochure .ey-lede+*{margin-top:24px}
.mfp-teal-brochure .ey-mt5{margin-top:20px}
.mfp-teal-brochure .ey-mt6{margin-top:24px}
.mfp-teal-brochure .ey-page>.ey-field+.ey-field:not(.ey-mt5):not(.ey-mt6){margin-top:20px}
.mfp-teal-brochure .ey-grid{display:grid;gap:16px}
.mfp-teal-brochure .ey-grid-2{grid-template-columns:1fr}
/* ---------- FIELDS ---------- */
.mfp-teal-brochure .ey-field{display:block}
.mfp-teal-brochure .ey-field>span{display:block;margin-bottom:6px;font-size:13px;font-weight:600;text-transform:uppercase;letter-spacing:.025em;line-height:1.3;color:var(--tb-teal-d)}
.mfp-teal-brochure .mf-field-group{margin:0}
.mfp.mfp-teal-brochure .ey-field .mf-field-label{display:none!important}
.mfp.mfp-teal-brochure .ey-field .mf-input,.mfp.mfp-teal-brochure .ey-field .mf-select,.mfp.mfp-teal-brochure .ey-field input[type=text],.mfp.mfp-teal-brochure .ey-field input[type=email],.mfp.mfp-teal-brochure .ey-field input[type=tel],.mfp.mfp-teal-brochure .ey-field input[type=number],.mfp.mfp-teal-brochure .ey-field input[type=date],.mfp.mfp-teal-brochure .ey-field select{width:100%!important;border:1.5px solid var(--tb-teal-m)!important;border-radius:12px!important;background:#fff!important;box-shadow:none!important;padding:12px 16px!important;font-family:inherit!important;font-size:15px!important;line-height:1.4!important;color:var(--tb-ink)!important;outline:none!important;transition:border-color .18s ease,box-shadow .18s ease}
.mfp.mfp-teal-brochure .ey-field .mf-input:hover,.mfp.mfp-teal-brochure .ey-field .mf-select:hover,.mfp.mfp-teal-brochure .ey-field select:hover{border-color:var(--tb-teal-r)!important}
.mfp.mfp-teal-brochure .ey-field .mf-input:focus,.mfp.mfp-teal-brochure .ey-field .mf-select:focus,.mfp.mfp-teal-brochure .ey-field input[type=text]:focus,.mfp.mfp-teal-brochure .ey-field input[type=email]:focus,.mfp.mfp-teal-brochure .ey-field input[type=tel]:focus,.mfp.mfp-teal-brochure .ey-field input[type=number]:focus,.mfp.mfp-teal-brochure .ey-field input[type=date]:focus,.mfp.mfp-teal-brochure .ey-field select:focus{border-color:var(--tb-teal)!important;box-shadow:0 0 0 3px rgba(42,157,143,.2)!important}
.mfp.mfp-teal-brochure .ey-field .mf-input::placeholder{color:#94a3b8!important}
.mfp.mfp-teal-brochure .ey-field textarea::placeholder{color:#94a3b8!important}
.mfp.mfp-teal-brochure .ey-field textarea,.mfp.mfp-teal-brochure .ey-field .mf-textarea{width:100%!important;min-height:120px!important;resize:none!important;border:1.5px solid var(--tb-teal-m)!important;border-radius:12px!important;background:#fff!important;box-shadow:none!important;padding:12px 16px!important;font-family:inherit!important;font-size:15px!important;line-height:1.6!important;color:var(--tb-ink)!important;outline:none!important;transition:border-color .18s ease,box-shadow .18s ease}
.mfp.mfp-teal-brochure .ey-field textarea:focus,.mfp.mfp-teal-brochure .ey-field .mf-textarea:focus{border-color:var(--tb-teal)!important;box-shadow:0 0 0 3px rgba(42,157,143,.2)!important}
.mfp.mfp-teal-brochure .ey-field .mf-field-error{margin-top:6px;font-size:12px;line-height:1.4;color:#c0453b}
.mfp.mfp-teal-brochure .mf-option-control{position:absolute!important;opacity:0!important;width:0!important;height:0!important;pointer-events:none!important}
/* ---------- CHIPS (interests) ---------- */
.mfp.mfp-teal-brochure .mf-option-group--chips{display:flex!important;flex-wrap:wrap!important;gap:8px!important;grid-template-columns:none!important;margin-top:2px}
.mfp.mfp-teal-brochure .mf-option-item--chips{margin:0!important;width:auto!important;cursor:pointer}
.mfp.mfp-teal-brochure .mf-option-item--chips .mf-option-ui{display:inline-flex;align-items:center;gap:6px;border:1.5px solid var(--tb-teal-m);border-radius:999px;background:var(--tb-teal-l);padding:6px 16px;font-size:13px;font-weight:500;line-height:1.3;color:var(--tb-teal-d);box-shadow:none;transition:all .18s ease}
.mfp.mfp-teal-brochure .mf-option-item--chips:hover .mf-option-ui{border-color:var(--tb-teal)}
.mfp.mfp-teal-brochure .mf-option-item--chips .mf-option-control:checked+.mf-option-ui{background:var(--tb-teal);border-color:var(--tb-teal);color:#fff}
.mfp.mfp-teal-brochure .mf-option-item--chips .mf-option-icon{width:auto;height:auto;flex:0 0 auto;border-radius:0;background:transparent;font-size:13px;color:inherit}
.mfp.mfp-teal-brochure .mf-option-item--chips .mf-option-label{display:inline;font-size:13px;font-weight:500;color:inherit}
.mfp.mfp-teal-brochure .mf-option-item--chips .mf-option-desc,.mfp.mfp-teal-brochure .mf-option-item--chips .mf-option-badge,.mfp.mfp-teal-brochure .mf-option-item--chips .mf-option-control:checked+.mf-option-ui .mf-option-check{display:none!important}
/* ---------- CARDS (programme / accommodation) ---------- */
.mfp.mfp-teal-brochure .mf-option-group--cards{display:grid!important;grid-template-columns:1fr!important;gap:12px!important;margin-top:2px}
.mfp.mfp-teal-brochure .mf-option-item--cards{margin:0!important;cursor:pointer}
.mfp.mfp-teal-brochure .mf-option-item--cards .mf-option-ui{display:flex;align-items:flex-start;gap:16px;border:1.5px solid var(--tb-teal-m);border-radius:16px;background:#fff;padding:16px;box-shadow:none;transition:all .18s ease}
.mfp.mfp-teal-brochure .mf-option-item--cards:hover .mf-option-ui{border-color:var(--tb-teal-r)}
.mfp.mfp-teal-brochure .mf-option-item--cards .mf-option-control:checked+.mf-option-ui{border-color:var(--tb-teal);background:var(--tb-teal-l);box-shadow:0 0 0 3px rgba(42,157,143,.13)}
.mfp.mfp-teal-brochure .mf-option-item--cards .mf-option-icon{display:flex;align-items:center;justify-content:center;width:44px;height:44px;flex:0 0 44px;border-radius:12px;background:var(--tb-teal-l);color:var(--tb-teal);font-size:20px;line-height:1;transition:all .18s ease}
.mfp.mfp-teal-brochure .mf-option-item--cards .mf-option-control:checked+.mf-option-ui .mf-option-icon{background:var(--tb-teal);color:#fff}
.mfp.mfp-teal-brochure .mf-option-item--cards .mf-option-copy{flex:1 1 auto;min-width:0}
.mfp.mfp-teal-brochure .mf-option-item--cards .mf-option-label{display:block;font-size:15px;font-weight:600;line-height:1.35;color:var(--tb-ink)}
.mfp.mfp-teal-brochure .mf-option-item--cards .mf-option-desc{display:block;margin-top:4px;font-size:14px;line-height:1.55;color:var(--tb-slate)}
.mfp.mfp-teal-brochure .mf-option-item--cards .mf-option-badge{align-self:flex-start;border-radius:999px;background:var(--tb-teal-l);padding:3px 10px;font-size:11px;font-weight:600;line-height:1.4;letter-spacing:.02em;color:var(--tb-teal-d);white-space:nowrap}
.mfp.mfp-teal-brochure .mf-option-item--cards .mf-option-control:checked+.mf-option-ui .mf-option-badge{background:#fff}
.mfp.mfp-teal-brochure .mf-option-check{display:none!important;align-self:flex-start;font-size:16px;font-weight:700;line-height:1.4;color:var(--tb-teal)}
.mfp.mfp-teal-brochure .mf-option-control:checked+.mf-option-ui .mf-option-check{display:inline-flex!important}
.mfp.mfp-teal-brochure [data-key='accommodation'] .mf-option-item--cards .mf-option-ui{display:block;position:relative}
.mfp.mfp-teal-brochure [data-key='accommodation'] .mf-option-item--cards .mf-option-check{position:absolute;top:14px;right:14px}
.mfp.mfp-teal-brochure [data-key='accommodation'] .mf-option-item--cards .mf-option-icon{width:36px;height:36px;flex:0 0 36px;margin-bottom:10px;font-size:18px}
.mfp.mfp-teal-brochure [data-key='accommodation'] .mf-option-item--cards .mf-option-desc{font-size:12px;margin-top:2px}
.mfp.mfp-teal-brochure [data-key='accommodation'] .mf-option-item--cards .mf-option-badge{display:inline-block;margin-top:8px}
/* ---------- PLAIN CHECKBOX ROWS (grant / newsletter / terms) ---------- */
.mfp.mfp-teal-brochure .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards){display:grid!important;gap:12px!important;grid-template-columns:none!important;margin-top:4px}
.mfp.mfp-teal-brochure .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards) .mf-option-item{margin:0!important;cursor:pointer}
.mfp.mfp-teal-brochure .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards) .mf-option-ui{display:flex;align-items:flex-start;gap:12px;font-size:14px;line-height:1.55;color:#4b5563}
.mfp.mfp-teal-brochure .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards) .mf-option-ui::before{content:'';flex:0 0 20px;width:20px;height:20px;margin-top:1px;border:1.5px solid var(--tb-teal-m);border-radius:6px;background:#fff;transition:all .18s ease}
.mfp.mfp-teal-brochure .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards) .mf-option-control:checked+.mf-option-ui::before{background:var(--tb-teal);border-color:var(--tb-teal);box-shadow:inset 0 0 0 3px #fff}
.mfp.mfp-teal-brochure .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards) .mf-option-icon{display:none!important}
.mfp.mfp-teal-brochure .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards) .mf-option-label{display:block;font-size:14px;font-weight:500;line-height:1.55;color:#4b5563}
.mfp.mfp-teal-brochure .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards) .mf-option-desc{display:block;margin-top:2px;font-size:12px;line-height:1.5;color:var(--tb-slate)}
.mfp.mfp-teal-brochure .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards) .mf-option-control:checked+.mf-option-ui .mf-option-check{display:none!important}
/* grant card: must beat the 6-class :not():not() plain-row rules above -> !important */
.mfp.mfp-teal-brochure [data-key='scholarship'] .mf-option-group .mf-option-ui{border:1.5px solid var(--tb-teal-m)!important;border-radius:16px!important;background:var(--tb-teal-l)!important;padding:16px!important}
.mfp.mfp-teal-brochure [data-key='scholarship'] .mf-option-group .mf-option-label{font-size:14px!important;font-weight:600!important;color:var(--tb-ink)!important}
.mfp.mfp-teal-brochure [data-key='scholarship'] .mf-option-group .mf-option-desc{font-size:12px!important;line-height:1.5!important;color:var(--tb-slate)!important}
/* ---------- REVIEW ---------- */
.mfp-teal-brochure .ey-review{overflow:hidden;border:1.5px solid var(--tb-teal-m);border-radius:16px;background:#fff}
.mfp-teal-brochure .ey-review>div{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:12px 16px;font-size:14px;line-height:1.4;background:#fff}
.mfp-teal-brochure .ey-review>div:nth-child(even){background:var(--tb-teal-l)}
.mfp-teal-brochure .ey-review span{font-size:14px;font-weight:400;color:var(--tb-slate)}
.mfp-teal-brochure .ey-review strong{font-size:14px;font-weight:600;text-align:right;color:var(--tb-ink)}
/* ---------- ACTIONS ---------- */
.mfp-teal-brochure .ey-actions{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:32px;padding-top:24px;border-top:1.5px solid var(--tb-teal-m)}
.mfp-teal-brochure .ey-back,.mfp-teal-brochure .ey-cancel{display:inline-flex;align-items:center;gap:8px;border:0;border-radius:12px;background:transparent;padding:10px 16px;font-size:14px;font-weight:600;line-height:1.2;white-space:nowrap;text-decoration:none;cursor:pointer;transition:color .18s ease}
.mfp-teal-brochure .ey-back{color:var(--tb-teal-d)}
.mfp-teal-brochure .ey-cancel{color:#94a3b8}
.mfp-teal-brochure .ey-back:hover{color:var(--tb-teal)}
.mfp-teal-brochure .ey-cancel:hover{color:#475569}
.mfp-teal-brochure .ey-count{margin:0 auto;font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.1em;line-height:1.2;white-space:nowrap;color:#94a3b8}
.mfp-teal-brochure .ey-next,.mfp-teal-brochure .ey-submit{display:inline-flex;align-items:center;gap:8px;border:0;border-radius:12px;background:var(--tb-teal);padding:10px 24px;font-size:14px;font-weight:600;line-height:1.4;white-space:nowrap;color:#fff;cursor:pointer;box-shadow:0 1px 2px rgba(30,42,42,.08);transition:opacity .18s ease,background .18s ease}
.mfp-teal-brochure .ey-submit{background:var(--tb-teal-d)}
.mfp-teal-brochure .ey-next:hover,.mfp-teal-brochure .ey-submit:hover{opacity:.9}
.mfp-teal-brochure .ey-next:disabled,.mfp-teal-brochure .ey-submit:disabled{background:var(--tb-teal-m);opacity:.4;box-shadow:none;cursor:not-allowed}
