/* ---------- TYPOGRAPHY LOCK (theme typography otherwise wins) ---------- */
.mfp.mfp-teal-brochure .ey-panel,.mfp.mfp-teal-brochure .ey-hero,.mfp.mfp-teal-brochure .ey-hero-foot,.mfp.mfp-teal-brochure .ey-lede,.mfp.mfp-teal-brochure .ey-hero-copy .ey-sub,.mfp.mfp-teal-brochure .ey-mission,.mfp.mfp-teal-brochure .mf-option-item--cards .mf-option-label{font-family:Inter,system-ui,-apple-system,'Segoe UI',sans-serif!important}
.mfp.mfp-teal-brochure .ey-hero h1,.mfp.mfp-teal-brochure .ey-page h2,.mfp.mfp-teal-brochure .ey-stats strong,.mfp.mfp-teal-brochure .ey-brand>span,.mfp.mfp-teal-brochure .ey-dot,.mfp.mfp-teal-brochure .ey-avatar{font-family:'DM Sans',Inter,system-ui,sans-serif!important}
/* ---------- RESPONSIVE ---------- */
@media (min-width:640px){.mfp-teal-brochure .ey-panel{padding:32px 40px}.mfp-teal-brochure .ey-card{padding:32px}.mfp-teal-brochure .ey-step-text{display:block}.mfp.mfp-teal-brochure [data-key='accommodation'] .mf-option-group--cards{grid-template-columns:repeat(3,minmax(0,1fr))!important}}
@media (min-width:1024px){.mfp-teal-brochure .ey-shell{grid-template-columns:min(420px,38%) minmax(0,1fr)}.mfp-teal-brochure .ey-hero{display:flex;flex-direction:column}.mfp-teal-brochure .ey-panel{padding:32px 48px}.mfp-teal-brochure .ey-grid-2{grid-template-columns:repeat(2,minmax(0,1fr))}}
/* MF-CHECKBOX-ROW-FIX-20260724 */
.mfp.mfp-teal-brochure .ey-field .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards){display:grid!important;grid-template-columns:minmax(0,1fr)!important}
.mfp.mfp-teal-brochure .ey-field .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards) .mf-option-item{display:block!important;width:100%!important;min-width:0!important}
.mfp.mfp-teal-brochure .ey-field .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards) .mf-option-ui{display:flex!important;flex-direction:row!important;align-items:flex-start!important;width:100%!important}
.mfp.mfp-teal-brochure .ey-field .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards) .mf-option-copy{flex:1 1 auto!important;min-width:0!important}
.mfp.mfp-teal-brochure .ey-field .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards) .mf-option-label{display:block!important;white-space:normal!important;overflow-wrap:break-word!important;word-break:normal!important}

/* [CardEqualHeight v20260801] Choice cards in a row are laid out on a grid, so each card was only as
   tall as its own copy and a 3-up row came out stepped. Stretch the items and let the option's
   own box fill its track. Scoped to this shell; nothing else in the design changes. */
.mfp.mfp-teal-brochure .mf-option-group--cards{align-items:stretch}
.mfp.mfp-teal-brochure .mf-option-group--cards .mf-option-item{display:flex}
.mfp.mfp-teal-brochure .mf-option-group--cards .mf-option-ui{width:100%;height:100%;box-sizing:border-box}
